visible_check:
from options import parse_options
for text, want in (("debug,level=high", {"debug": True, "level": "high"}), ("dry", {"dry": True})):
    got = parse_options(text)
    assert got == want, (text, got)
    for key, value in want.items():
        if value is True:
            assert got[key] is True, (text, key, got[key])

